# -*- coding: utf-8 -*-
"""Build a readable local report from the saved experiment, not a scorer."""
import html,json
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2];esc=lambda x:html.escape(str(x),quote=True)
inputs=json.loads((HERE/'source-only-inputs.json').read_text());run=ROOT/'poc/data/parallel-b-link-2026-11-05-v2';rows=[json.loads(f.read_text()) for f in run.glob('*/result.json')]
style='''*{box-sizing:border-box}body{margin:0;background:#f5f4f0;color:#222;font:16px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1250px;margin:auto;padding:40px 24px 80px}h1{font-size:34px;line-height:1.25;margin:12px 0}h2{margin:35px 0 12px;font-size:24px}.muted{color:#666}.badge{display:inline-block;background:#ebe8df;border-radius:24px;padding:4px 12px;font-weight:700}.card,.case{background:white;border:1px solid #e2e0d9;border-radius:14px;padding:20px;margin:12px 0}.alert{background:#fff5df;border-left:5px solid #bd8c36}.flow,.comparison{display:grid;grid-template-columns:1fr 1fr;gap:12px}.box{background:#f6f5f1;border:1px solid #e2e0d9;border-radius:12px;padding:16px}.share{grid-column:span 2;text-align:center}.arrow{text-align:center;grid-column:span 2;font-size:23px;color:#777;line-height:1}.record{border-top:1px solid #eee;padding:10px 0;font-size:14px}.record p{margin:5px 0}blockquote{font-size:13px;color:#666;margin:6px 0;padding-left:10px;border-left:3px solid #ccc}small{color:#777}details{margin:8px 0}summary{cursor:pointer;font-weight:650}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:600px;overflow:auto;background:#f5f4f0;padding:14px;border-radius:8px;font:12px/1.5 ui-monospace,monospace}a{color:#444;text-decoration:underline}@media(max-width:800px){.flow,.comparison{display:block}.box{margin:10px 0}main{padding:20px 14px}}'''
htmls=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>并行抽取迭代记录</title><style>'+style+'</style><main><span class="badge">真实实验 · 10 篇 × 两版 × 3 次</span><h1>新观点与已有观点证据：迭代进度</h1><p class="muted">同一篇文章和同一份历史题库，对照两版“已有观点证据”说明。模型每篇、每版各跑 3 次；下面可以展开每条实际结果。</p><div class="card alert"><b>当前状态：这一版还不稳定。</b> 指引条件有时保住了，但也有漏利润、错误日期、多问题关联和证据编号冲突。新一轮使用金标的测量暂缓：Micron 文章中有三个金标问题的口径可能超出了原文，等待确认。<a href="ruler-conflict-2026-11-05.zh.md">看原文与金标逐项对照</a>。<details><summary>直接看冲突是什么</summary><p>文章原文：“the AI hyperscalers plan to spend $650 billion ... this year, next year that figure could be over $1 trillion.” 文章没有列出四家公司。金标却要求以“四大云厂商合计”开 2026 和 2027 两题。</p><p>同一篇文章提到 DRAM 和 NAND 价格上涨、供应紧张，但没有明确写“DRAM 合同价”或 HBM；金标要求开“DRAM（含 HBM）合同价”问题。原文之外能否做这两类口径限定，尚待你判断。</p></details></div><h2>两路怎么工作</h2><div class="flow"><div class="box share"><b>同一篇文章 + 文章到来前的题库快照</b></div><div class="arrow">↓ 同时 ↓</div><div class="box"><b>A · 找新观点</b><p>找新的重要问题，并把文章里支持或反对它的证据带上。</p></div><div class="box"><b>B · 找旧观点的新证据</b><p>找文章中能影响已有问题的信息，不额外开题。</p></div><div class="arrow">↓ 两路结果经过检查 ↓</div><div class="box share"><b>先分配唯一证据编号，再交给后续步骤</b><br>同一来源在两路出现时，不能算成两份独立证实。实际跨路去重仍未验证。</div></div><h2>以后怎么打分</h2><div class="card"><b>Alex 的决定：只分有帮助／没帮助。</b> 不再为了打分把有帮助的信息细分成核心或辅助；现有金标里的核心和辅助合并计数，不收算没帮助，可选仍不扣分；直接用原金标，不需要重做。旧金标和历史分数保留原样。</div><h2>真实结果，先看问题</h2><div class="comparison"><div class="card"><b>这轮出现的回归</b><p>一次结果把文章的发表日填成 NVIDIA 和 CFO 的原始发言日；另一次结果给 14 条不同证据用了同一个编号。还有季度利润漏失及关联过宽。</p></div><div class="card"><b>一个局部改善信号</b><p>“1080 亿美元收入指引假设中国销售为零”：修改版 3 次里有 2 次把假设和指引一起保住；对照版 3 次里有 1 次分成两条保住。样本小，不代表整体更好。</p></div></div><div class="card"><b>编号离线重放：</b>真实保存的那 14 条证据，旧编号让匹配查找只形成 3 个键；实验中按记录位置分配唯一编号后形成 14 个键。临时数据库中的初步重放覆盖了新建、合并、拒绝，但独立复核又发现请求绑定和匹配决定检查的缺口；这些结果还不能作为交接安全或生产入库验收。</div><div class="card"><b>范围说明：</b>这 60 次只测试 B；A 的编号保护和 A/B 合并正在离线验证。六篇文章属于已使用过的 golden-v5 开发集，另外四篇来自历史研究；没有运行未见过的 30 篇测试集，也没有完成真实模型匹配与最终判断。</div><h2>逐篇展开：原文、题库、六次结果</h2>']
for i,src in enumerate(inputs,1):
 htmls.append('<article class="case"><h3>'+str(i).zfill(2)+' · '+esc(src['title'])+'</h3><p class="muted">'+esc(src['input_id'])+' · 快照 '+str(len(src['questions']))+' 个问题</p><details><summary>看完整文章</summary><pre>'+esc(src['article'])+'</pre></details><details><summary>看当时已有的问题</summary><pre>'+esc('\n'.join(q['view_id']+' | '+q['question'] for q in src['questions']))+'</pre></details>')
 for arm in ('control','treatment'):
  for n in (1,2,3):
   r=next(r for r in rows if r['id']==src['input_id'] and r['variant']==arm and r['draw']==n);h=r['handover'];label=('对照' if arm=='control' else '修改版')+' · 第 '+str(n)+' 次'
   htmls.append('<details><summary>'+label+'：'+str(len(h['evidence']))+' 条保留，'+str(len(h['dropped']))+' 条丢弃或合并</summary>')
   if h['dropped']:htmls.append('<p>丢弃／合并：'+esc(json.dumps(h['dropped'],ensure_ascii=False))+'</p>')
   if r['raw_multi_home'] or r['checked_multi_home']:htmls.append('<p>多问题关联：原始 '+esc(json.dumps(r['raw_multi_home'],ensure_ascii=False))+'；检查后 '+esc(json.dumps(r['checked_multi_home'],ensure_ascii=False))+'</p>')
   for e in h['evidence']:
    htmls.append('<div class="record"><b>'+esc(e['id'])+'</b> · 关联 '+esc(', '.join(e['links']) or '无')+'<p>'+esc(e['one_line'])+'</p><blockquote>'+esc(e['quote'])+'</blockquote><small>原始来源：'+esc(e['original_who'] or '未写')+' · 原始日期：'+esc(e['original_day'] or '未写')+' · 来源类型：'+esc(e['tier'])+'</small></div>')
   htmls.append('<details><summary>查看完整原始回答</summary><pre>'+esc(json.dumps(r['answer'],ensure_ascii=False,indent=2))+'</pre></details></details>')
 htmls.append('</article>')
htmls.append('<h2>说明和完整记录</h2><div class="card"><p><a href="arm-log.zh.md">迭代记录</a> · <a href="b-diagnostic-independent-review.md">独立逐篇复核</a> · <a href="source-map-corrections.md">预先原文核对与分歧</a> · <a href="../2026-11-05-parallel-thesis-evidence-poc/report.html">第一轮 A/B 可视化和两套 prompt</a></p><p>冻结标准与金标没有修改。第二位来源读者看到过旧结果摘要，所以不是完全盲读。下游真实匹配、写入和判断还没有完成端到端验证。</p></div></main></html>')
(HERE/'iteration.html').write_text(''.join(htmls));print(HERE/'iteration.html')
